(3552404, 495250, 67728, '<td valign="top">Awesome dof!  Great job catching this prebattle shot.</td>', 'Awesome dof!  Great job catching this prebattle shot.', '2007-04-16 14:29:18.000000', NULL, 1),
(3552405, 497839, 43774, '<td valign="top">Wow that''s incredible! I''ve never seen bees like that before! Very good detail and clarity here.</td>', 'Wow that''s incredible! I''ve never seen bees like that before! Very good detail and clarity here.', '2007-04-16 14:29:33.000000', NULL, 1),
(3552406, 496076, 43774, '<td valign="top">The colours, clarity and detail in this are all excellent.</td>', 'The colours, clarity and detail in this are all excellent.', '2007-04-16 14:29:37.000000', NULL, 1),
(3552407, 497832, 43774, '<td valign="top">Very pretty, I love that the butterfly/moth mimics the colour of the flower. Excellent choice of background colour (this looks like a set-up shot to me rather than one found in nature, not that there''s anything wrong with that).</td>', 'Very pretty, I love that the butterfly/moth mimics the colour of the flower. Excellent choice of background colour (this looks like a set-up shot to me rather than one found in nature, not that there''s anything wrong with that).', '2007-04-16 14:29:48.000000', NULL, 1),
(3552408, 497418, 43774, '<td valign="top">Wow, great job! Love the DOF and the colours here.</td>', 'Wow, great job! Love the DOF and the colours here.', '2007-04-16 14:29:54.000000', NULL, 1),
(3552409, 497893, 43774, '<td valign="top">Lovely composition, great DOF and colour.</td>', 'Lovely composition, great DOF and colour.', '2007-04-16 14:30:00.000000', NULL, 1),
(3552411, 496556, 43774, '<td valign="top">Oh my, this comes across as a very sad photo. The flies look like tears from the horse''s eyes. I think it''s great when you can evoke emotion from an insect photo. Well done.</td>', 'Oh my, this comes across as a very sad photo. The flies look like tears from the horse''s eyes. I think it''s great when you can evoke emotion from an insect photo. Well done.', '2007-04-16 14:30:25.000000', NULL, 1),
(3552412, 496621, 43774, '<td valign="top">Very good composition and colours, I really like this.</td>', 'Very good composition and colours, I really like this.', '2007-04-16 14:30:32.000000', NULL, 1),
(3552413, 497976, 43774, '<td valign="top">Odd title but a good photo. I like the colour and detail</td>', 'Odd title but a good photo. I like the colour and detail', '2007-04-16 14:30:36.000000', NULL, 1),
(3552414, 497842, 43774, '<td valign="top">Cool, it certainly is camouflauged. Good DOF here</td>', 'Cool, it certainly is camouflauged. Good DOF here', '2007-04-16 14:30:39.000000', NULL, 1),
(3552415, 497315, 43774, '<td valign="top">Love the colours on the wings. Good composition and DOF.</td>', 'Love the colours on the wings. Good composition and DOF.', '2007-04-16 14:30:42.000000', NULL, 1),
(3552416, 497453, 43774, '<td valign="top">Love that you captured more than one in the photo.....I just love that green butterfly.</td>', 'Love that you captured more than one in the photo.....I just love that green butterfly.', '2007-04-16 14:30:52.000000', NULL, 1),
(3552417, 497762, 43774, '<td valign="top">Excellent detail and colour on the fly. Flower is blown out in spots, that distracts a tiny bit, but the great DOF makes up for that.</td>', 'Excellent detail and colour on the fly. Flower is blown out in spots, that distracts a tiny bit, but the great DOF makes up for that.', '2007-04-16 14:30:55.000000', NULL, 1),
(3552418, 497872, 67728, '<td valign="top">Very cute idea!  Love the castle.  Bugs are a little difficult to see.</td>', 'Very cute idea!  Love the castle.  Bugs are a little difficult to see.', '2007-04-16 14:30:56.000000', NULL, 1),
(3552419, 497834, 43774, '<td valign="top">Lovely colour, flower and butterfly match!</td>', 'Lovely colour, flower and butterfly match!', '2007-04-16 14:31:02.000000', NULL, 1),
(3552420, 498135, 43774, '<td valign="top">Very good detail in the butterfly....did you try taking any pics on an angle? I usually find a diagonal composition more pleasing than a straight on one.</td>', 'Very good detail in the butterfly....did you try taking any pics on an angle? I usually find a diagonal composition more pleasing than a straight on one.', '2007-04-16 14:31:08.000000', NULL, 1),
(3552422, 497465, 43774, '<td valign="top">Very pretty, lovely colours and clarity.</td>', 'Very pretty, lovely colours and clarity.', '2007-04-16 14:31:13.000000', NULL, 1),
(3552423, 494931, 43774, '<td valign="top">Very pretty, lovely spring photo. Bee is a bit lost but the clarity and detail in the photo is excellent, especially on the flowers.</td>', 'Very pretty, lovely spring photo. Bee is a bit lost but the clarity and detail in the photo is excellent, especially on the flowers.', '2007-04-16 14:31:20.000000', NULL, 1),
(3552424, 498045, 43774, '<td valign="top">Very good diagonal composition, good clarity and DOF.</td>', 'Very good diagonal composition, good clarity and DOF.', '2007-04-16 14:31:26.000000', NULL, 1),
(3552425, 496220, 43774, '<td valign="top">Lovely colours and composition. Really wish there were a bit more DOF.</td>', 'Lovely colours and composition. Really wish there were a bit more DOF.', '2007-04-16 14:31:32.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3552426, 497316, 43774, '<td valign="top">Love the colours here, very good detail and clarity as well in the beetle.</td>', 'Love the colours here, very good detail and clarity as well in the beetle.', '2007-04-16 14:31:38.000000', NULL, 1),
(3552427, 495776, 43774, '<td valign="top">Nice, very clear, good exposure.</td>', 'Nice, very clear, good exposure.', '2007-04-16 14:31:43.000000', NULL, 1),
(3552428, 498081, 43774, '<td valign="top">Excellent colours here. I would like to see a bit more DOF. A bit of grain here too and is that a dirt speck from your camera I see?</td>', 'Excellent colours here. I would like to see a bit more DOF. A bit of grain here too and is that a dirt speck from your camera I see?', '2007-04-16 14:31:51.000000', NULL, 1),
(3552430, 498017, 43774, '<td valign="top">Great title, good composition and DOF. Colour and clarity are excellent.</td>', 'Great title, good composition and DOF. Colour and clarity are excellent.', '2007-04-16 14:31:59.000000', NULL, 1),
