(3552432, 497328, 43774, '<td valign="top">They''re cool looking bugs. Good diagonal composition and colour.</td>', 'They''re cool looking bugs. Good diagonal composition and colour.', '2007-04-16 14:32:13.000000', NULL, 1),
(3552434, 497813, 43774, '<td valign="top">Very clear with good colours. Did you use a flash? The light seems a bit bright and I can see the bug''s shadow.</td>', 'Very clear with good colours. Did you use a flash? The light seems a bit bright and I can see the bug''s shadow.', '2007-04-16 14:32:24.000000', NULL, 1),
(3552435, 498210, 43774, '<td valign="top">Pretty colours and good DOF</td>', 'Pretty colours and good DOF', '2007-04-16 14:32:28.000000', NULL, 1),
(3552439, 496100, 43774, '<td valign="top">Very good detail, lighting is pretty good, a bit dark on the head but not enough to ruin the photo....8 from me.</td>', 'Very good detail, lighting is pretty good, a bit dark on the head but not enough to ruin the photo....8 from me.', '2007-04-16 14:32:50.000000', NULL, 1),
(3552440, 497290, 43774, '<td valign="top">Lovely colours, good saturation.</td>', 'Lovely colours, good saturation.', '2007-04-16 14:32:54.000000', NULL, 1),
(3552441, 497091, 43774, '<td valign="top">Very good DOF.....great colour and clarity. Those aphids are tiny so you did a great job.</td>', 'Very good DOF.....great colour and clarity. Those aphids are tiny so you did a great job.', '2007-04-16 14:32:58.000000', NULL, 1),
(3552442, 497904, 43774, '<td valign="top">Very good macro, great clarity and colour.</td>', 'Very good macro, great clarity and colour.', '2007-04-16 14:33:02.000000', NULL, 1),
(3552443, 495749, 43774, '<td valign="top">Very cool, I like the setting with the dried leaves.</td>', 'Very cool, I like the setting with the dried leaves.', '2007-04-16 14:33:07.000000', NULL, 1),
(3552445, 497139, 43774, '<td valign="top">Love the colours here and the fact that the flower and the moth match (that is such a cool moth too!).</td>', 'Love the colours here and the fact that the flower and the moth match (that is such a cool moth too!).', '2007-04-16 14:33:17.000000', NULL, 1),
(3552447, 497492, 43774, '<td valign="top">Very good clarity and detail in this.</td>', 'Very good clarity and detail in this.', '2007-04-16 14:33:23.000000', NULL, 1),
(3552448, 497080, 43774, '<td valign="top">Beautiful butterfly and colours, very clear.</td>', 'Beautiful butterfly and colours, very clear.', '2007-04-16 14:33:26.000000', NULL, 1),
