(3552453, 497475, 43774, '<td valign="top">Good example of mother nature''s camouflauge. Nice diagonal composition, clear with good earth tones.</td>', 'Good example of mother nature''s camouflauge. Nice diagonal composition, clear with good earth tones.', '2007-04-16 14:33:45.000000', NULL, 1),
(3552454, 496312, 43774, '<td valign="top">Pretty, good composition and great colour. Light might be a bit too harsh.</td>', 'Pretty, good composition and great colour. Light might be a bit too harsh.', '2007-04-16 14:33:49.000000', NULL, 1),
(3552455, 498239, 43774, '<td valign="top">Nice diagonal composition, very good colour.</td>', 'Nice diagonal composition, very good colour.', '2007-04-16 14:33:52.000000', NULL, 1),
(3552456, 498136, 43774, '<td valign="top">Very nice pose and detail, might be a bit dark but not much.</td>', 'Very nice pose and detail, might be a bit dark but not much.', '2007-04-16 14:34:01.000000', NULL, 1),
(3552457, 495996, 43774, '<td valign="top">Very pretty, great colours and clarity.</td>', 'Very pretty, great colours and clarity.', '2007-04-16 14:34:05.000000', NULL, 1),
(3552459, 498133, 43774, '<td valign="top">Lovely colour and light in this. Good composition.</td>', 'Lovely colour and light in this. Good composition.', '2007-04-16 14:34:10.000000', NULL, 1),
(3552460, 497284, 43774, '<td valign="top">Very cool, great diagonal composition, good colours. Love those eyes!</td>', 'Very cool, great diagonal composition, good colours. Love those eyes!', '2007-04-16 14:34:14.000000', NULL, 1),
(3552461, 497278, 43774, '<td valign="top">I think the harsh light and shadows are hurting this photo. I do like the composition and the colour.</td>', 'I think the harsh light and shadows are hurting this photo. I do like the composition and the colour.', '2007-04-16 14:34:17.000000', NULL, 1),
(3552462, 496161, 43774, '<td valign="top">Very good colours but I think you need more DOF to get the entire butterfly in focus....or at least the majority of it.</td>', 'Very good colours but I think you need more DOF to get the entire butterfly in focus....or at least the majority of it.', '2007-04-16 14:34:19.000000', NULL, 1),
(3552463, 498050, 43774, '<td valign="top">Nice composition, like that the caterpillar is looking at the camera. Seems underexposed though</td>', 'Nice composition, like that the caterpillar is looking at the camera. Seems underexposed though', '2007-04-16 14:34:24.000000', NULL, 1),
(3552464, 497476, 43774, '<td valign="top">Good composition and DOF. Different than the typical ladybug pose on a leaf/flower.</td>', 'Good composition and DOF. Different than the typical ladybug pose on a leaf/flower.', '2007-04-16 14:34:28.000000', NULL, 1),
(3552465, 496038, 43774, '<td valign="top">Very good colours and composition. I really wish there were more DOF so that the head of the beetle was also in focus.</td>', 'Very good colours and composition. I really wish there were more DOF so that the head of the beetle was also in focus.', '2007-04-16 14:34:31.000000', NULL, 1),
