(3552467, 498222, 43774, '<td valign="top">Pretty flowers, shame that it''s underexposed because the bee is lost in the darkness.</td>', 'Pretty flowers, shame that it''s underexposed because the bee is lost in the darkness.', '2007-04-16 14:34:38.000000', NULL, 1),
(3552468, 497533, 43774, '<td valign="top">Pretty, love the pose but it''s underexposed/too dark.</td>', 'Pretty, love the pose but it''s underexposed/too dark.', '2007-04-16 14:34:41.000000', NULL, 1),
(3552469, 498007, 43774, '<td valign="top">Not very! LOL You have some good detail in this, it''s very clear and close.</td>', 'Not very! LOL You have some good detail in this, it''s very clear and close.', '2007-04-16 14:34:45.000000', NULL, 1),
(3552470, 497837, 43774, '<td valign="top">Good composition, did you use a flash? There''s a harsh light spot on the ladybug''s back. Bug seems a bit dark.</td>', 'Good composition, did you use a flash? There''s a harsh light spot on the ladybug''s back. Bug seems a bit dark.', '2007-04-16 14:34:48.000000', NULL, 1),
(3552471, 497930, 43774, '<td valign="top">Very clear but the DOF might be a bit too shallow.</td>', 'Very clear but the DOF might be a bit too shallow.', '2007-04-16 14:34:54.000000', NULL, 1),
(3552472, 496636, 43774, '<td valign="top">Good DOF and detail but I think it needs to be a bit brighter.</td>', 'Good DOF and detail but I think it needs to be a bit brighter.', '2007-04-16 14:34:57.000000', NULL, 1),
(3552473, 498234, 43774, '<td valign="top">Pretty butterfly with good colours in the photo but I don''t think I like the shadows.</td>', 'Pretty butterfly with good colours in the photo but I don''t think I like the shadows.', '2007-04-16 14:35:00.000000', NULL, 1),
(3552474, 498229, 43774, '<td valign="top">Good clarity on the butterfly and grass although I think the large OOF rock in front will hurt this photo. Was it possible to get closer?</td>', 'Good clarity on the butterfly and grass although I think the large OOF rock in front will hurt this photo. Was it possible to get closer?', '2007-04-16 14:35:03.000000', NULL, 1),
(3552476, 497894, 43774, '<td valign="top">Very close and cool. If you had taken this so the branch/twig was on the diagonal I think it would have made the composition stronger and more pleasing.</td>', 'Very close and cool. If you had taken this so the branch/twig was on the diagonal I think it would have made the composition stronger and more pleasing.', '2007-04-16 14:35:06.000000', NULL, 1),
(3552477, 497752, 67728, '<td valign="top">This is a great idea.  Wonderful composition and I like the shadow of the castle behind the butterfly.  Need more focus on the butterfly.  I like the black and white, but would also like to see this one in color.</td>', 'This is a great idea.  Wonderful composition and I like the shadow of the castle behind the butterfly.  Need more focus on the butterfly.  I like the black and white, but would also like to see this one in color.', '2007-04-16 14:35:09.000000', NULL, 1),
(3552478, 497954, 43774, '<td valign="top">Wow this is close. A bit busy with all those legs, my eyes keep looking for something to focus on. Good clarity and detail.</td>', 'Wow this is close. A bit busy with all those legs, my eyes keep looking for something to focus on. Good clarity and detail.', '2007-04-16 14:35:10.000000', NULL, 1),
(3552479, 497741, 43774, '<td valign="top">Very clear, good detail (I can see the hairs on the fly!). Seems a bit too dark/underexposed though.</td>', 'Very clear, good detail (I can see the hairs on the fly!). Seems a bit too dark/underexposed though.', '2007-04-16 14:35:13.000000', NULL, 1),
(3552480, 498061, 43774, '<td valign="top">Interesting looking bugs, have no idea what they are. Nice colours, good DOF. Seems a little bit dull.</td>', 'Interesting looking bugs, have no idea what they are. Nice colours, good DOF. Seems a little bit dull.', '2007-04-16 14:35:16.000000', NULL, 1),
(3552481, 497906, 43774, '<td valign="top">Very good colour, bug seems a bit fuzzy.</td>', 'Very good colour, bug seems a bit fuzzy.', '2007-04-16 14:35:19.000000', NULL, 1),
(3552482, 498121, 43774, '<td valign="top">Not bad to catch a bee/fly in flight!</td>', 'Not bad to catch a bee/fly in flight!', '2007-04-16 14:35:23.000000', NULL, 1),
(3552483, 497852, 43774, '<td valign="top">Cute! Good idea for those of us in cold climates. Good colour and DOF here.</td>', 'Cute! Good idea for those of us in cold climates. Good colour and DOF here.', '2007-04-16 14:35:28.000000', NULL, 1),
(3552484, 497857, 43774, '<td valign="top">Good detail on the bug. If you had taken this so the branch/stick were a bit more on the diagonal I think it would make for a stronger composition.</td>', 'Good detail on the bug. If you had taken this so the branch/stick were a bit more on the diagonal I think it would make for a stronger composition.', '2007-04-16 14:35:31.000000', NULL, 1),
