(3552486, 497190, 43774, '<td valign="top">Wow they''re cool bugs! Love their colours, great colour in the photo as well as clarity. I really wish the big one in front were in focus.</td>', 'Wow they''re cool bugs! Love their colours, great colour in the photo as well as clarity. I really wish the big one in front were in focus.', '2007-04-16 14:35:42.000000', NULL, 1),
(3552487, 496817, 43774, '<td valign="top">Very good colours, light/flash seems a bit harsh. Great detail on the bee.</td>', 'Very good colours, light/flash seems a bit harsh. Great detail on the bee.', '2007-04-16 14:35:45.000000', NULL, 1),
(3552488, 497673, 43774, '<td valign="top">Good lighting here</td>', 'Good lighting here', '2007-04-16 14:35:48.000000', NULL, 1),
(3552489, 496810, 43774, '<td valign="top">Lovely colours</td>', 'Lovely colours', '2007-04-16 14:35:52.000000', NULL, 1),
(3552490, 496595, 43774, '<td valign="top">Cute pose, great colour and clarity. This is one that will look excellent cropped closer I think.</td>', 'Cute pose, great colour and clarity. This is one that will look excellent cropped closer I think.', '2007-04-16 14:35:54.000000', NULL, 1),
(3552491, 497633, 43774, '<td valign="top">You caught a good pose but it seems to be underexposed/too dark.</td>', 'You caught a good pose but it seems to be underexposed/too dark.', '2007-04-16 14:35:58.000000', NULL, 1),
(3552492, 497769, 43774, '<td valign="top">Very good colour and clarity here</td>', 'Very good colour and clarity here', '2007-04-16 14:36:03.000000', NULL, 1),
