(3552495, 497287, 43774, '<td valign="top">Good timing to get the bee in flight....good DOF. Shame there isn''t more detail in the bee, it''s very dark in spots.</td>', 'Good timing to get the bee in flight....good DOF. Shame there isn''t more detail in the bee, it''s very dark in spots.', '2007-04-16 14:36:14.000000', NULL, 1),
(3552496, 495414, 43774, '<td valign="top">Ewwwwwww! LOL Funny title. Good clarity although the light and shadows are harsh.</td>', 'Ewwwwwww! LOL Funny title. Good clarity although the light and shadows are harsh.', '2007-04-16 14:36:20.000000', NULL, 1),
(3552498, 496845, 43774, '<td valign="top">I''ve never seen one of these in real life (we don''t have them here) and I am not sure I want to! Interesting lighting here, good detail.</td>', 'I''ve never seen one of these in real life (we don''t have them here) and I am not sure I want to! Interesting lighting here, good detail.', '2007-04-16 14:36:26.000000', NULL, 1),
(3552499, 497342, 43774, '<td valign="top">Good diagonal composition and colours.</td>', 'Good diagonal composition and colours.', '2007-04-16 14:36:29.000000', NULL, 1),
(3552500, 498066, 43774, '<td valign="top">Pretty with good colours</td>', 'Pretty with good colours', '2007-04-16 14:36:37.000000', NULL, 1),
(3552501, 497131, 67728, '<td valign="top">Awesome shot!  Makes me want to run. Great dof</td>', 'Awesome shot!  Makes me want to run. Great dof', '2007-04-16 14:36:38.000000', NULL, 1),
(3552502, 498219, 43774, '<td valign="top">Cute setup, good composition, could be a bit brighter. Seems under exposed a bit.</td>', 'Cute setup, good composition, could be a bit brighter. Seems under exposed a bit.', '2007-04-16 14:36:41.000000', NULL, 1),
(3552503, 498126, 43774, '<td valign="top">Cute! Bug is very clear, not fond of the OOF flower on the left.</td>', 'Cute! Bug is very clear, not fond of the OOF flower on the left.', '2007-04-16 14:36:47.000000', NULL, 1),
