(3555244, 497465, 70514, '<td valign="top">Nice and simple.  I like the composition and contrast.</td>', 'Nice and simple.  I like the composition and contrast.', '2007-04-17 13:21:31.000000', NULL, 1),
(3555328, 498238, 66952, '<td valign="top">Very funny! Maybe the lighting could be better, but still, very funny.</td>', 'Very funny! Maybe the lighting could be better, but still, very funny.', '2007-04-17 14:10:01.000000', NULL, 1),
(3555337, 498005, 66952, '<td valign="top">Nice composition, I like the arrangement of the butterfly, plant, and the shallow DOF to blur the background. Maybe a little deeper DOF would be better, to get the whole butterfly in focus, but that''s really a judgement call. It works either way.</td>', 'Nice composition, I like the arrangement of the butterfly, plant, and the shallow DOF to blur the background. Maybe a little deeper DOF would be better, to get the whole butterfly in focus, but that''s really a judgement call. It works either way.', '2007-04-17 14:12:01.000000', NULL, 1),
(3555382, 496161, 66952, '<td valign="top">Nice job getting up close and personal with the butterfly. That''s hard in minimal editing. I like the decision to cut off the ends of the wings to show more of the middle of the butterfly. I think that works pretty well.  The little beastie could be a bit sharper, though.</td>', 'Nice job getting up close and personal with the butterfly. That''s hard in minimal editing. I like the decision to cut off the ends of the wings to show more of the middle of the butterfly. I think that works pretty well.  The little beastie could be a bit sharper, though.', '2007-04-17 14:28:18.000000', NULL, 1),
(3555393, 498007, 66952, '<td valign="top">Eeeek!!! I wouldn''t want to meet him on a dark night. The on-camera flash is a bit harsh, but otherwise, you''ve captured this guy well.</td>', 'Eeeek!!! I wouldn''t want to meet him on a dark night. The on-camera flash is a bit harsh, but otherwise, you''ve captured this guy well.', '2007-04-17 14:32:06.000000', NULL, 1),
(3555407, 498062, 66952, '<td valign="top">Nice. Good, tight, pretty sharp capture of the yellowjacket. If it weren''t minimal editing, I''d suggest cropping tighter, because the background doesn''t help the shot, but nevermind. The lighting is a bit harsh. Maybe try finding the guy earlier or later in the day and shooting then (yeah, right).</td>', 'Nice. Good, tight, pretty sharp capture of the yellowjacket. If it weren''t minimal editing, I''d suggest cropping tighter, because the background doesn''t help the shot, but nevermind. The lighting is a bit harsh. Maybe try finding the guy earlier or later in the day and shooting then (yeah, right).', '2007-04-17 14:35:46.000000', NULL, 1),
(3555411, 497446, 66952, '<td valign="top">Love the colors, and the bee in its natural setting. The lighting is a bit harsh, maybe go out a little earlier in the morning, and the bee and flower could be a little sharper, but it''s a good start.</td>', 'Love the colors, and the bee in its natural setting. The lighting is a bit harsh, maybe go out a little earlier in the morning, and the bee and flower could be a little sharper, but it''s a good start.', '2007-04-17 14:36:54.000000', NULL, 1),
(3555482, 498230, 8139, '<td valign="top">can''t wait to see your setup configuration. Good Microphoto.</td>', 'can''t wait to see your setup configuration. Good Microphoto.', '2007-04-17 15:23:38.000000', NULL, 1),
