(3558585, 497453, 45919, '<td valign="top">Really like the colours in the green butterfly closeup and the textures in the leaves.</td>', 'Really like the colours in the green butterfly closeup and the textures in the leaves.', '2007-04-18 09:28:15.000000', NULL, 1),
(3558589, 497872, 45919, '<td valign="top">I think a crop of the background at the top would have done made this a much nicer photo.</td>', 'I think a crop of the background at the top would have done made this a much nicer photo.', '2007-04-18 09:29:06.000000', NULL, 1),
