(3558593, 498125, 45919, '<td valign="top">Interesting idea with the black light but it detracts from the scorpion, would love to seen the photo taken from the same angle and perspective without the black light.</td>', 'Interesting idea with the black light but it detracts from the scorpion, would love to seen the photo taken from the same angle and perspective without the black light.', '2007-04-18 09:30:40.000000', NULL, 1),
(3558595, 496954, 45919, '<td valign="top">Nice although the head is somewhat hidden because of the choice of surface colour.</td>', 'Nice although the head is somewhat hidden because of the choice of surface colour.', '2007-04-18 09:31:43.000000', NULL, 1),
(3558598, 497256, 45919, '<td valign="top">Very nice, bet you waited a while for that.</td>', 'Very nice, bet you waited a while for that.', '2007-04-18 09:32:49.000000', NULL, 1),
