(3558609, 497284, 45919, '<td valign="top">Very nice, love the detail you have managed to capture in the wings and love the depth of field.  Well done.</td>', 'Very nice, love the detail you have managed to capture in the wings and love the depth of field.  Well done.', '2007-04-18 09:36:20.000000', NULL, 1),
(3558614, 496839, 45919, '<td valign="top">Nice concept.  A crop around the bee or a different colour flower so that the Bee stood out would have scored higher for me.</td>', 'Nice concept.  A crop around the bee or a different colour flower so that the Bee stood out would have scored higher for me.', '2007-04-18 09:37:55.000000', NULL, 1),
(3558615, 497336, 45919, '<td valign="top">Lovely detail, well done.</td>', 'Lovely detail, well done.', '2007-04-18 09:38:46.000000', NULL, 1),
(3558621, 497015, 45919, '<td valign="top">Had the wings been more in focus, this would have led to a higher score.</td>', 'Had the wings been more in focus, this would have led to a higher score.', '2007-04-18 09:40:34.000000', NULL, 1),
(3558624, 497954, 45919, '<td valign="top">Very nice.</td>', 'Very nice.', '2007-04-18 09:41:12.000000', NULL, 1),
(3558625, 498234, 45919, '<td valign="top">Love the colour contrasts.</td>', 'Love the colour contrasts.', '2007-04-18 09:41:28.000000', NULL, 1),
(3558627, 496571, 45919, '<td valign="top">Different...</td>', 'Different...', '2007-04-18 09:41:56.000000', NULL, 1),
