(3559587, 495250, 30268, '<td valign="top">awesome!! you have a spectacular eye!</td>', 'awesome!! you have a spectacular eye!', '2007-04-18 13:35:03.000000', NULL, 1),
(3559768, 496783, 61651, '<td valign="top">Some might say this is just a too-centered image of a fly, but for me the whole composition projects a physical depth and a moodiness that I find very attractive. Even if this was just a spur of the moment "snapshot" for you and the composition is accidental, kudos for your "happy accident". It scores tops from me, but I suspect it won''t score well with DPC voters overall - hopefully I will be wrong. Anyway, I like it very much. :)</td>', 'Some might say this is just a too-centered image of a fly, but for me the whole composition projects a physical depth and a moodiness that I find very attractive. Even if this was just a spur of the moment "snapshot" for you and the composition is accidental, kudos for your "happy accident". It scores tops from me, but I suspect it won''t score well with DPC voters overall - hopefully I will be wrong. Anyway, I like it very much. :)', '2007-04-18 14:31:44.000000', NULL, 1),
(3560007, 497936, 41357, '<td valign="top">enough with the woddy</td>', 'enough with the woddy', '2007-04-18 15:58:01.000000', NULL, 1),
