(3560131, 498126, 28172, '<td valign="top">Great shot! Really nice selective focus and nice colors! 10</td>', 'Great shot! Really nice selective focus and nice colors! 10', '2007-04-18 16:35:58.000000', NULL, 1),
(3560141, 497256, 28172, '<td valign="top">Beautiful shot! 10 from me!</td>', 'Beautiful shot! 10 from me!', '2007-04-18 16:37:33.000000', NULL, 1),
(3560202, 497960, 39663, '<td valign="top">Oh My!! My jaw dropped. So strange and memorable.</td>', 'Oh My!! My jaw dropped. So strange and memorable.', '2007-04-18 16:56:04.000000', NULL, 1),
(3560269, 497964, 33672, '<td valign="top">Some mighty big fleas! Original idea.</td>', 'Some mighty big fleas! Original idea.', '2007-04-18 17:18:47.000000', NULL, 1),
(3560292, 497752, 43774, '<td valign="top">Interesting, I don''t think I''ve ever seen a butterfly on a dragon statue before! I can''t help but think that this would be better in colour. I would love to see the colours of the butterfly. Your title doesn''t make sense gramatically, sorry.</td>', 'Interesting, I don''t think I''ve ever seen a butterfly on a dragon statue before! I can''t help but think that this would be better in colour. I would love to see the colours of the butterfly. Your title doesn''t make sense gramatically, sorry.', '2007-04-18 17:28:18.000000', NULL, 1),
(3560327, 498133, 77248, '<td valign="top">No vote, just commenting. This is such a beautiful shot!</td>', 'No vote, just commenting. This is such a beautiful shot!', '2007-04-18 17:36:50.000000', NULL, 1),
(3560380, 496100, 74821, '<td valign="top">Nice</td>', 'Nice', '2007-04-18 17:52:32.000000', NULL, 1),
